#include <stdio.h>
#include <stdlib.h>

/* 摇 n 把骰子（每把 1 到 6），一把一把印在同一行，每把后面跟一个空格 */
void roll_dice(int n) {
    for (int i = 0; i < n; i++) {
        printf("%d ", rand() % 6 + 1);
    }
}

int main(void) {
    srand({seed});
    printf("掷 {n} 把：");
    roll_dice({n});
    printf("\n");
    return 0;
}
